import re, sys, glob, os
SP = os.path.dirname(os.path.abspath(__file__))
REG = 'D:/the-synaptic-sea-2d/docs/registry/architecture.yaml'
raw = open(REG, 'rb').read().decode('utf-8')
crlf = raw.count('\r\n'); lf = raw.count('\n')
print('CRLF', crlf, 'LF total', lf)
L = raw.replace('\r\n', '\n').split('\n')
if L and L[-1] == '':
    trailing = True; L = L[:-1]
else:
    trailing = False

KEYSEC = {'state': 'state_ownership', 'contract': 'interfaces', 'system': 'performance_budgets',
          'target_fps': 'performance_budgets', 'purpose': 'api_decisions', 'pattern': 'forbidden_patterns'}
HEAD = re.compile(r'^  - (state|contract|system|target_fps|purpose|pattern): (.*?)\s*(#.*)?$')
stats = {}
def bump(sec, k):
    stats.setdefault(sec, {'added': 0, 'revised': 0, 'refs': 0})[k] += 1

def find(name, key=None):
    out = []
    for i, l in enumerate(L):
        m = HEAD.match(l)
        if m and m.group(2).strip().strip('"') == name and (key is None or m.group(1) == key):
            out.append(i)
    return out

def end_of(i):
    j = i + 1
    while j < len(L) and L[j].startswith('    '):
        j += 1
    return j

def fields(block):
    f = []  # list of (key, [lines])
    for l in block:
        m = re.match(r'^    ([a-z_]+):', l)
        if m:
            f.append([m.group(1), [l]])
        elif f:
            f[-1][1].append(l)
        else:
            raise Exception('bad ' + l)
    return f

def val(lines):
    first = lines[0].split(':', 1)[1].strip()
    if first.startswith('"'):
        j = first.rfind('"')
        first = first[:j + 1]
    else:
        first = re.sub(r'\s+#.*$', '', first)
    rest = [x.strip() for x in lines[1:]]
    return ' '.join([first] + rest).strip()

def refpath(l):
    return re.sub(r'\s+#.*$', '', l.strip()[2:]).strip()

def refs_of(lines):
    return [refpath(x) for x in lines[1:] if x.strip().startswith('- ')]

def clean_list(lines):
    # strip trailing comments on list items
    out = [lines[0]]
    for x in lines[1:]:
        if x.strip().startswith('- '):
            out.append('      - ' + refpath(x))
        else:
            out.append(x)
    return out

def refadd(name, paths, key=None):
    idxs = find(name, key)
    if not idxs:
        print('REF TARGET MISSING', name); return
    for i in idxs:
        e = end_of(i)
        blk = L[i + 1:e]
        have = []
        last = None
        for k, l in enumerate(blk):
            if l.startswith('    referenced_by:'):
                last = k
                n = k + 1
                while n < len(blk) and blk[n].startswith('      - '):
                    have.append(refpath(blk[n])); last = n; n += 1
        new = [p for p in paths if p not in have]
        if not new:
            continue
        add = ['      - ' + p for p in new]
        if last is not None:
            pos = i + 1 + last + 1
            L[pos:pos] = add
        else:
            # insert before added: or at end
            pos = e
            for k, l in enumerate(blk):
                if l.startswith('    added:'):
                    pos = i + 1 + k; break
            L[pos:pos] = ['    referenced_by:'] + add
        bump(KEYSEC[HEAD.match(L[i]).group(1)], 'refs')

def insert_new(entry_lines, key):
    sec = KEYSEC[key]
    s = L.index(sec + ':')
    ex = next(i for i in range(s, len(L)) if L[i].startswith('# Example:'))
    p = ex
    while L[p - 1].strip() == '':
        p -= 1
    L[p:p] = entry_lines
    bump(sec, 'added')

def revise(i, newlines):
    e = end_of(i)
    old = fields(L[i + 1:e])
    new = fields(newlines[1:])
    oldd = {k: v for k, v in old}
    out = [newlines[0]]
    for k, ln in new:
        ln = clean_list(ln)
        if k == 'referenced_by':
            union = refs_of(ln)
            for p in refs_of(oldd.get('referenced_by', [''])):
                if p not in union:
                    union.append(p)
            ln = ['    referenced_by:'] + ['      - ' + p for p in union]
        elif k == 'added':
            ln = oldd['added'] if 'added' in oldd else ln
        elif k == 'revised':
            ln = ['    revised: 2026-10-28']
        elif k in oldd and val(oldd[k]) != val(ln):
            ln = ['    # was: ' + val(oldd[k])] + ln
        out += ln
    for k, ln in old:
        if k not in [x[0] for x in new]:
            print('  old-only field kept', k); out += ln
    L[i:e] = out
    bump(KEYSEC[HEAD.match(newlines[0]).group(1)], 'revised')

def upsert(text):
    ls = text.rstrip('\n').split('\n')
    m = HEAD.match(ls[0])
    assert m, ls[0]
    key, name = m.group(1), m.group(2).strip().strip('"')
    if key == 'target_fps':
        name = '%s fps' % name
    if key == 'target_fps':
        ex = [i for i, l in enumerate(L) if l.startswith('  - target_fps: ' + m.group(2).strip())]
        # same-number target_fps entry from another ADR would clash; treat as existing
        idxs = ex
    else:
        idxs = find(name, key)
    ls = [clean_list_line(x) for x in ls]
    if idxs:
        revise(idxs[0], ls)
    else:
        insert_new(ls, key)

def clean_list_line(x):
    if x.startswith('      - '):
        return '      - ' + refpath(x) if 'adr-' in x else x
    return x

for fn in ['d1.txt', 'd2.txt', 'd3.txt', 'd4.txt', 'd5.txt']:
    for part in open(os.path.join(SP, fn), encoding='utf-8').read().split('\n=====\n'):
        upsert(part)

