 '0009': A + 'adr-0009-presentation-subscriber-contract.md',
 '0010': A + 'adr-0010-source-layout-static-typing-and-lint-enforcement.md',
}
REFS = {
 '0004': ['write_outside_writescope_or_setter_dirty', 'owner_callable_contract', 'block_registration', 'presentation_submit_without_handle'],
 '0005': ['payload_size_check', 'write_outside_writescope_or_setter_dirty', 'fault_domain_table', 'restore_epoch'],
 '0006': ['control_plane', 'owner_callable_contract', 'block_as_resource_or_node', 'fault_domain_table', 'kernel_autoload_or_global', 'static_content_catalogs', 'content_loading', 'frame_order'],
 '0008': ['presentation_clock', 'tick_alpha', 'frame_order'],
 '0009': ['presentation_submit_without_handle', 'cosmetic_phase_from_tick_counter', 'kernel_autoload_or_global', 'tick_alpha', 'owner_callable_contract'],
 '0010': ['kernel_autoload_or_global', 'physics_callback_tick_source', 'await_process_frame_in_sim_or_presentation', 'command_constructed_outside_kernel', 'write_outside_writescope_or_setter_dirty', 'void_or_value_returning_owner_callable', 'presentation_submit_without_handle', 'block_as_resource_or_node', 'content_directory_scan', 'mutable_or_resource_catalog', 'loader_side_effect_or_foreign_boot_code', 'content_file_read', 'frame_order', 'simulation_clock', 'content_export'],
}
for adr, names in REFS.items():
    for n in names:
        refadd(n, [P[adr]])

